  /** Show the position's FEN in each turn's message. The moves so far are always shown, and so is the starting FEN of a game from another position. */
  show_fen: boolean;
  /** Show the board as text in each turn's message. */
  show_board: boolean;
  /** The moves listed in each turn's message. `both`: System 1's candidates, when there are any, and every legal move. `legal`: every legal move. `candidates`: only the candidates. `none`: no list. A restricted turn always lists the permitted moves. */
