  /** Also ask System 1 to score the position. Recorded only; it doesn't change the move. */
  with_eval: boolean;
  /** Also ask System 1 whether the position needs calculation and has tactics. Recorded only; it doesn't change the move. */
  with_nouls: boolean;
  /** The signal compared with the threshold. `margin`: the top move's probability minus the second's. `confidence`: System 1's own confidence in its ranking. */
